 lead:[{who:"Schwester Hilde",say:"Blutdruck hundertzweiundachtzig zu achtundneunzig. Puls vierundneunzig. Bitte wiederholen.",want:"182.{0,12}98|hundertzweiundachtzig",ok:"Richtig. Temperatur sechsunddreißig acht.",no:"Noch einmal: hundert – zwei – und – achtzig zu acht – und – neunzig.",model:"182 zu 98, Puls 94."},
  {who:"Schwester Hilde",say:"Zucker hundertsiebenundsechzig. Schreiben Sie das auf. Wie viel?",want:"167|hundertsiebenundsechzig",ok:"Gut. Jetzt fragen Sie ihn selbst.",no:"Hundert – sieben – und – sechzig.",model:"167."}],
 open:"Gude. Ich bin's wieder. Der Blutdruck.",
 ans:{name:"Heckmann, Erwin. Das wissen Sie doch.",dob:"Dritter Neunter achtundfünfzig.",size:"Ein Meter sechsundsiebzig. Vierundneunzig Kilo.",gp:"Doktor Lang in Dossenheim. Telefon: null sechs zwei zwei eins, acht sechs, vier sieben, eins fünf.",
  cc:"Ich habe Kopfweh. Und der Blutdruck ist hoch.",onset:"Seit heute Morgen. Seit sechs Uhr.",site:"Hinten. Im Kopf hinten.",severity:"Fünf. Vielleicht sechs.",
  meds:"Ramipril, fünf Milligramm. Morgens eine. Metformin, tausend. Morgens eine, abends eine.",pmh:"Blutdruck seit 2010. Zucker seit 2016.",allergy:"Nein. Keine.",smoke:"Zehn am Tag. Früher zwanzig.",alcohol:"Ein Viertel Wein am Abend. Manchmal zwei.",
  a_neuro:"Nein. Ich sehe gut. Ich spreche normal.",a_chest:"Nein. Keine Schmerzen in der Brust.",a_dizzy:"Ein bisschen. Beim Aufstehen.",a_nausea:"Nein.",home:"Hauptstraße hundertvierzehn, Dossenheim.",empathy:"Danke.",close:"Wie hoch war er jetzt?"},
