 hid:[{id:"h1",on:"meds",if:"re:heute|genommen|vergessen|jeden tag|regelmäßig",a:"Heute habe ich sie nicht genommen. Und gestern auch nicht. Die Packung ist leer."},{id:"h2",on:"x_bp",if:"re:wann|uhr|wie oft|noch einmal|zweimal|danach",a:"Um acht noch einmal: hundertneunzig zu hundert."},{id:"h3",on:"alcohol",if:"re:gestern|wie viel|wieviel",a:"Gestern war Kerwe. Da waren es fünf Viertel."}],
 back:[{q:"Ist das gefährlich, Herr Dokter?",after:["x_bp"],want:"hoch|medikament|tablette|kontroll|gefaehr|nicht|ruhig",ok:"Alla gut. Dann nehme ich sie wieder.",no:"Gefährlich – ja oder nein?"}],
